To demonstrate the power of the **M5 chip's GPU** (specifically its high-bandwidth Unified Memory and hardware-accelerated shading), the best way to show off is through a **Real-Time Metal Fragment Shader**. 

While the M5 features specific hardware ray-tracing units, a "Liquid Plasma" shader is the perfect "eye candy" because it forces the GPU to calculate complex trigonometric math for every single pixel 60-120 times per second.

Since you want this to be runnable easily, I have combined the **Metal Shader source code** directly into the Swift file so it compiles at runtime.

### 1. The `main.swift`
This file creates a window and hosts a Metal view that renders a high-performance "Aurora" effect.

```swift
import SwiftUI
import AppKit
import Metal
import MetalKit

// --- Metal Shader Source ---
// This is the "Magic" that runs on the M5 GPU cores.
let shaderSource = """
#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float time;
    float resolution[2];
};

fragment float4 aurora_fragment(float4 position [[stage_in]],
                                 constant Uniforms &uniforms [[buffer(0)]]) {
    float2 uv = position.xy / float2(uniforms.resolution[0], uniforms.resolution[1]);
    float2 p = uv * 3.0;

    float t = uniforms.time * 0.5;

    // Complex math to create the "Liquid/Aurora" look
    float val = sin(p.x + t) + sin(p.y + t) + sin((p.x + p.y) * 0.5 + t);
    val += sin(p.x * 1.5 + t * 1.2) * 0.5;
    val += sin(p.y * 2.0 - t * 0.8) * 0.5;

    float r = 0.5 + 0.5 * sin(val + t);
    float g = 0.5 + 0.5 * sin(val + t + 2.0);
    float b = 0.5 + 0.5 * sin(val + t + 4.0);

    return float4(r * 0.4, g * 0.7, b * 0.9, 1.0);
}
"""

// --- Metal Renderer ---
class Renderer: NSObject, MTKViewDelegate {
    var device: MTLDevice!
    var commandQueue: MTLCommandQueue!
    var pipelineState: MTLRenderPipelineState!
    var startTime = Date()

    struct Uniforms {
        var time: Float
        var resolution: SIMD2<Float>
    }

    init(metalView: MTKView) {
        super.init()
        self.device = MTLCreateSystemDefaultDevice()
        self.commandQueue = device.makeCommandQueue()

        let library = try! device.makeLibrary(source: shaderSource, options: [.compilationMode(.default)])
        let fragmentFunction = library.makeFunction(name: "aurora_fragment")!

        let pipelineDescriptor = MTLRenderPipelineDescriptor()
        pipelineDescriptor.device = device
        pipelineDescriptor.colorAttachments[0].pixelFormat = metalView.colorPixelFormat
        pipelineDescriptor.fragmentFunction = fragmentFunction

        pipelineState = try! device.makeRenderPipelineState(descriptor: pipelineDescriptor)
        metalView.delegate = self
        metalView.device = device
    }

    func draw(in view: MTKView) {
        guard let drawable = view.currentDrawable,
              let descriptor = view.currentRenderPassDescriptor,
              let pipeline = pipelineState else { return }

        let commandBuffer = commandQueue.makeCommandBuffer()
        let encoder = commandBuffer?.makeRenderCommandEncoder(descriptor: descriptor)

        var uniforms = Uniforms(
            time: Float(Date().timeIntervalSince(startTime)),
            resolution: SIMD2<Float>(Float(view.drawableSize.width), Float(view.drawableSize.height))
        )

        encoder?.setRenderPipelineState(pipeline)
        encoder?.setFragment_vertex__buffer(buffer: nil, offset: 0, index: 0) // Placeholder
        encoder?.setFragmentBytes(&uniforms, length: MemoryLayout<Uniforms>.size, index: 0)

        // Draw a full-screen triangle/quad
        encoder?.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)

        encoder?.endEncoding()
        commandBuffer?.present(drawable)
        commandBuffer?.commit()
    }

    func mtkView(_ view: MTKView, drawableSizeWillChange size: CGSize) {}
}

// --- SwiftUI Layer ---
struct MetalViewWrapper: NSViewRepresentable {
    func makeNSView(context: Context) -> MTKView {
        let mtkView = MTKView()
        mtkView.clearColor = MTLClearColor(red: 0, green: 0, blue: 0, alpha: 1)
        mtkView.preferredFramesPerSecond = 60
        // Initialize renderer
        _ = Renderer(metalView: mtkView) 
        // Note: In a production app, we'd store the renderer in a StateObject
        return mtkView
    }

    func updateNSView(_ nsView: MTKView, context: Context) {}
}

struct ContentView: View {
    var body: some View {
        ZStack {
            MetalViewWrapper() // The GPU-heavy content

            VStack {
                Text("M5 GPU Power")
                    .font(.system(size: 48, weight: .black, design: .monospaced))
                    .foregroundColor(.white)
                    .shadow(radius: 10)

                Text("Real-time Metal Shader")
                    .font(.headline)
                    .foregroundColor(.white.opacity(0.8))

                Text("Running at 60 FPS")
                    .font(.caption)
                    .padding(8)
                    .background(.ultraThinMaterial)
                    .cornerRadius(10)
                    .foregroundColor(.white)
            }
            .padding()
        }
        .frame(width: 600, height: 600)
    }
}

// --- Boilerplate ---
class AppDelegate: NSObject, NSApplicationDelegate {
    var window: NSWindow!

    func applicationDidFinishLaunching(_ notification: Notification) {
        let contentView = ContentView()

        window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 600, height: 600),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false
        )
        window.center()
        window.title = "M5 GPU Demo"
        window.contentView = NSHostingView(rootView: contentView)
        window.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }
}

let app = NSApplication.shared
let delegate = AppDelegate()
app.delegate = delegate
app.setActivationPolicy(.regular)
app.run()
```

